'use strict';

// MODULES //

var trim = require( '@stdlib/string/trim' );
var generateDtypes = require( './generate_dtypes.js' );
var extractTypesJsonArray = require( './extract_types_json_array.js' );
var formatTypesArray = require( './format_types_array.js' );
var extractDataImports = require( './extract_data_imports.js' );
var extractDataArray = require( './extract_data_array.js' );
var extractAddonIncludes = require( './extract_addon_includes.js' );
var extractAddonFunctions = require( './extract_addon_functions.js' );
var extractAddonTypes = require( './extract_addon_types.js' );
var extractAddonData = require( './extract_addon_data.js' );


// MAIN //

/**
* Generates dtype dispatch and native addon template variables for scaffold.sh.
*
* @param {string} basePkg - base package name
* @returns {Object} object containing template variable strings
*
* @example
* var vars = generateTemplateVars( 'acosd' );
* // returns { 'TYPES_ARRAY': '...', 'TYPES_JSON_ARRAY': '[11,11,12,12]', ... }
*/
function generateTemplateVars( basePkg ) {
	var filteredMatches;
	var matches;
	var vars;
	var i;

	// Generate and filter matches table:
	matches = generateDtypes( basePkg );
	filteredMatches = [];
	for ( i = 0; i < matches.length; i++ ) {
		if ( matches[ i ][ 0 ] !== 'generic' && matches[ i ][ 1 ] !== 'generic' ) {
			filteredMatches.push( matches[ i ] );
		}
	}

	vars = {};

	// Generate template variable content:
	vars.TYPES_ARRAY = formatTypesArray( matches );
	vars.TYPES_JSON_ARRAY = trim( extractTypesJsonArray( matches ) );
	vars.DATA_IMPORTS = extractDataImports( matches );
	vars.DATA_ARRAY = extractDataArray( matches );
	vars.ADDON_INCLUDES = extractAddonIncludes( filteredMatches );
	vars.ADDON_FUNCTIONS = extractAddonFunctions( filteredMatches );
	vars.ADDON_TYPES = extractAddonTypes( filteredMatches );
	vars.ADDON_DATA = extractAddonData( filteredMatches );
	vars.ADDON_NUM_FUNCTIONS = filteredMatches.length.toString();

	return vars;
}


// EXPORTS //

module.exports = generateTemplateVars;
